-- Path to Ascension: event-completed quest-log views of the client tutorials. They carry no
-- rewards of their own; the tutorial reward is granted by the Path to Ascension claim.
INSERT INTO `quest_template` (`ID`, `QuestLevel`, `MinLevel`, `QuestSortID`, `Flags`, `AllowableRaces`, `LogTitle`,
`LogDescription`, `QuestDescription`, `QuestCompletionLog`, `RequiredNpcOrGo1`, `RequiredNpcOrGo2`,
`RequiredNpcOrGoCount1`, `RequiredNpcOrGoCount2`, `ObjectiveText1`, `ObjectiveText2`)
VALUES
(81000, -1, 60, -379, 64, 0, 'Path to Ascension: Interesting Ethereals', 'Speak to the Ethereals inside the Auction House.', 'Interested Ethereals have taken up residence inside the Auction House offering fantastical goods and useful services.  Ameer Greatluck is an expert at finding all things lost and returning them to you.  Marazz is a master of appearances and transmogfication. Tranforming everything from your boots to your fireball.  Tiraxis runs the Ethereal Bazaar, offering exclusive cosmetic items with limited stock and Temporal Contracts.  Speak to each Ethereal and explore their goods and services.', 'Talk to Ameer Greatluck\nTalk to Tiraxis', 80420, 80421, 1, 1, 'Talk to Ameer Greatluck', 'Talk to Tiraxis'),
(149176, -1, 70, -379, 64, 0, 'Path to Ascension: Mythic+ Vendor', 'Talk to Edrim Skysong in Shattrath', 'Edrim Skysong is keenly interested in your Mythic Adventures, and can aid you in many ways. He''ll offer you gear, help you upgrade existing equipment, and recycle unwanted mythic items for additional Mythic Coins,', 'Talk to Edrim Skysong in Shattrath', 0, 0, 0, 0, '', ''),
(149179, -1, 58, -379, 64, 0, 'Path to Ascension: The Dark Portal', 'Make your way to the Blasted Lands.', 'Your time to confront the Burning Legion has come. Take the Portal to the Blasted Lands, located atop the Mage Tower in the Mage District of Stormwind.', 'Use the Blasted Lands Portal and speak to Watch Commander Relthorn Netherwane', 0, 0, 0, 0, NULL, NULL),
(149180, -1, 58, -379, 192, 0, 'Path to Ascension: Into Outland', 'Make your way to the Blasted Lands.', 'Your time to confront the Burning Legion has come. Take the Portal in Orgrimmar to the Blasted Lands, located in The Valley of spirits.', 'Use the Blasted Lands Portal and speak toWarlord Dar''toon.', 0, 0, 0, 0, NULL, NULL),
(149181, -1, 58, -379, 64, 1101, 'Path to Ascension: Trials & Challenges', 'Visit with Stony Tark, Keeper of Trials.', 'Stony Tark stands as the unwavering sentinel at the threshold of greatness, the Keeper of Trials and Master of Ceremonies. Trials are customizable gamemodes that profoundly change the difficulty of your experience and offer a variety of vanity and cosmetic rewards.', 'Talk with Stony Tark', 0, 0, 0, 0, NULL, NULL),
(149182, -1, 58, -379, 64, 690, 'Path to Ascension: Trials & Challenges', 'Visit with Stony Tark, Keeper of Trials.', 'Stony Tark stands as the unwavering sentinel at the threshold of greatness, the Keeper of Trials and Master of Ceremonies. Trials are customizable gamemodes that profoundly change the difficulty of your experience and offer a variety of vanity and cosmetic rewards.', 'Talk with Stony Tark', 0, 0, 0, 0, NULL, NULL),
(149183, -1, 70, -379, 64, 0, 'Path to Ascension: Take to the skys!', 'Speak with Olrokk, the Flight Instructor, in Shadowmoon Valley.', 'You''ve proven your strength on the ground, but the skies of Outland await. If you wish to soar above its shattered lands, you’ll need the proper training—and a flying mount. Seek out the expert flying trainer in Shadowmoon Valley. They''ll guide you on the path to taking flight.', 'Speak with Olrokk in Shadowmoon Valley.', 0, 0, 0, 0, NULL, NULL),
(149184, -1, 70, -379, 64, 0, 'Path to Ascension: Take to the skys!', 'Speak with IIsa Thunderbrew, the Flight Instructor, in Shadowmoon Valley.', 'You''ve proven your strength on the ground, but the skies of Outland await. If you wish to soar above its shattered lands, you’ll need the proper training—and a flying mount. Seek out the expert flying trainer in Shadowmoon Valley. They''ll guide you on the path to taking flight.', 'Speak with IIsa Thunderbrew, the Flight Instructor, in Shadowmoon Valley.', 0, 0, 0, 0, NULL, NULL),
(149185, -1, 10, -379, 64, 0, 'Path to Ascension: Mystic Enchantment Quality', 'Add 1 enchant of each quality to your collection.', 'Mystic Enchants are separated by quality; Rare, Epic, Legendary, and Artifact. These enchants will enhance spells, change abilities, or improve stats in different ways depending on their quality.', 'Collect a Mystic Enchant of each quality; Rare, Epic, and Legendary.', 0, 0, 0, 0, NULL, NULL),
(149186, -1, 58, -379, 64, 0, 'Path to Ascension: Fully Loaded', 'Fill every open Mystic Enchant slot in the Active Enchants UI.', 'Mystic Enchants are your key to maximizing the potential of your character. You will therefor want to make certain that you''ve applied all of the enchants that you can from your collection to your active enchants. You can activates a total of 11 Mystic Enchants in a single specialization; 6 Rare, 3 Epic, 1 Legendary, and 1 Artifact.', 'Fill every active slot with an enchantment of the appropriate quality.', 0, 0, 0, 0, NULL, NULL),
(149187, -1, 15, -379, 64, 0, 'Path to Ascension: Activating Mystic Scrolls', '- Obtain a Mystic Enchanting Scroll by defeating enemies or trading other players.  - Interact with a Mystic Enchanting Altar found in your Capital City or in the World and select Enchant Scrolls tab.  - Activate a Mystic Scroll and apply it to an Active Enchant slot.', 'Mystic Enchanting Scrolls can be obtained by defeating enemies, found hidden throughout the world, or by trading other players.    Once obtained, visit a Mystic Enchanting Altar to apply a Mystic Scroll to gain its powers! Mystic Enchanting Altars can often be found summoned in Capital Cities, or you can venture into the world to visit one. Their locations are marked on the world map.    Mystic Enchants are key to unlocking your power as a Hero. Find Mystic Enchants that empower your spells or unlock whole new archetypes to increase your power.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(149188, -1, 15, -379, 64, 0, 'Path to Ascension: Reforging and Mystic Extracts', '- Obtain an Untarnished Mystic Scroll from the Enchant Scrolls tab of the Mystic Altar.  - Reforge your Mystic Scroll to obtain new Mystic Enchants. You can continue reforging any Mystic Scroll until you find an Enchant you want to keep.  - Reforging Mystic Scrolls grants you progress towards a Mystic Extract.  - Reforge 5 times. Continue Reforging until you earn a Mystic Extract.', 'Visit an Altar and select the Enchant Scrolls tab, then Obtain an Untarnished Mystic Scroll.  Clicking Reforge on a Mystic Scroll will roll a new Mystic Enchant on the scroll and overwrite any existing enchant on the scroll. Reforging consumes Mystic Runes, or gold if you are out of Mystic Runes!  Each time you Reforge you earn experience towards your Mystic Enchanting level. Each level earned grants you a Mystic Extract which can be used to permanently apply Mystic Enchants to your Enchant Collection. This collection is shared across all characters on the realm!  Mystic Enchanting Altars can often be found summoned in Capital Cities, or you can venture into the world to visit one. Their locations are marked on the world map.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(149189, -1, 15, -379, 64, 0, 'Path to Ascension: Mystic Enchant Collection', 'Select a Mystic Scroll from the Scrolls tab in the Mystic Altar, then hit Save to Collection.', 'Saving a Mystic Enchant to your collection permanently unlocks it for all characters on this realm, allowing you to apply that enchant from an Altar whenever you want without needing a scroll!  Adding Enchants to your collection destroys the scrolls and consumes a Mystic Extract. There is no limit to how many Mystic Extracts you can acquire, so be sure to save your favorite Mystic Enchants and ones critical to your build.  Select a Mystic Scroll from the Scrolls tab in the Mystic Altar, then hit Save to Collection.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(189190, -1, 15, -379, 64, 0, 'Path to Ascension: Using Your Mystic Enchant Collection', 'Visit an Altar and apply a Mystic Enchant from your Enchant Collection to an Active Enchant slot.', 'Open the Enchant Collection tab from a Mystic Altar, select an Enchant from your Enchant Collections and apply it to an Active Enchant slot, then select Save Changes to activate your Mystic Enchant.  Activating Enchants from your collection requires Mystic Orbs, which can be earned from Daily Quests on the Call Board, Dungeons and Raids, Battlegrounds or defeating enemies in the world!  1 Legendary Enchant can be applied to the large center slot in the Altar.  3 Epic Enchants can be applied in the medium slots in the inner ring.  You can apply as many Rare and Uncommon Enchants in the remaining slots as you''d like. Many of these Enchants can stack up to 3 times. Mousing over the Enchant in the collection reveals its max stack size.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580134, -1, 15, -379, 64, 0, 'Path to Ascension: Reforging and Mystic Extracts', '- Obtain an Untarnished Mystic Scroll from the Enchant Scrolls tab of the Mystic Altar.  - Reforge your Mystic Scroll to obtain new Mystic Enchants. You can continue reforging any Mystic Scroll until you find an Enchant you want to keep.  - Reforging Mystic Scrolls grants you progress towards a Mystic Extract.  - Reforge 5 times. Continue Reforging until you earn a Mystic Extract.', 'Visit an Altar and select the Enchant Scrolls tab, then Obtain an Untarnished Mystic Scroll.  Clicking Reforge on a Mystic Scroll will roll a new Mystic Enchant on the scroll and overwrite any existing enchant on the scroll. Reforging consumes Mystic Runes, or gold if you are out of Mystic Runes!  Each time you Reforge you earn experience towards your Mystic Enchanting level. Each level earned grants you a Mystic Extract which can be used to permanently apply Mystic Enchants to your Enchant Collection. This collection is shared across all characters on the realm!  Mystic Enchanting Altars can often be found summoned in Capital Cities, or you can venture into the world to visit one. Their locations are marked on the world map.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580135, -1, 15, -379, 64, 0, 'Path to Ascension: Mystic Enchant Collection', 'Select a Mystic Scroll from the Scrolls tab in the Mystic Altar, then hit Save to Collection.', 'Saving a Mystic Enchant to your collection permanently unlocks it for all characters on this realm, allowing you to apply that enchant from an Altar whenever you want without needing a scroll!  Adding Enchants to your collection destroys the scrolls and consumes a Mystic Extract. There is no limit to how many Mystic Extracts you can acquire, so be sure to save your favorite Mystic Enchants and ones critical to your build.  Select a Mystic Scroll from the Scrolls tab in the Mystic Altar, then hit Save to Collection.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580136, -1, 8, -379, 0, 0, 'Path to Ascension: Vanity Auctions', 'Buy any Vanity Weapon or Armor from the Auction House', 'Buy any Vanity Weapon or Armor from the Auction House', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
(580137, -1, 8, -379, 0, 0, 'Path to Ascension: Collect Transmog Appearances', 'Collect Transmog Appearances', 'Collect Transmog Appearances', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
(580138, -1, 60, -379, 64, 0, 'Path to Ascension: End Game Builds', 'Open the Hero Architect and load a level 70 build.', 'Max level builds are significantly more powerful than leveling builds. It''s vital that you upgrade your build at max level to succeed in end-game content.  You can find many end-game ready builds in the Hero Architect. Hit N, then click the Hero Architect Tab, then select either Level 60 or 70 Builds depending on your current level.  You can scroll through high rated end game builds to find one that matches your playstyle!   End-game builds rely on Mystic Enchants. Each build will show the required Mystic Enchants at the bottom of the build page. You should acquire the Legendary and Epic enchants suggested immediately to ensure the build works as intended, then seek out the Blue and Green enchants as soon as possible.  It is highly recommended you try out featured builds before trying to create your own end-game build. You can also reference high rated builds when creating your own to start with a strong foundation.  Once you choose a build and begin to grow comfortable with it, don''t be afraid to experiment and adjust the build to your specific style of play.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580139, -1, 8, -379, 0, 0, 'Path to Ascension: PvE Power', 'Reach 460 PVE Power by equipping soulbound gear', 'Reach 460 PVE Power by equipping soulbound gear', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
(580140, -1, 8, -379, 0, 0, 'Path to Ascension: PvP Power', 'Equip PvP or Bloodforged gear in each gear slot to reach 250 PVP Power.', 'Equip PvP or Bloodforged gear in each gear slot to reach 250 PVP Power.', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
(580141, -1, 8, -379, 0, 0, 'Path to Ascension: Gear Up!', 'Equip more powerful gear to reach 40 item level.', 'Equip more powerful gear to reach 40 item level.', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
(580142, -1, 15, -379, 64, 0, 'Path to Ascension: Epic Mystic Enchant Collection', '- Acquire Epic Mystic Enchant Scrolls by Reforging, discovering them in the world, or the Auction House.  - Visit an Altar and save 3 Epic Mystic Enchants to your Enchant Collection.', 'Save 3 Epic Enchants into your collection. You can Reforge Scrolls until you acquire an Epic Enchant you''d like to save, or search the Auction House for Enchants that empower your spells and talents!  Visit an Altar and select an Epic Mystic Scroll from the Scrolls tab, then hit Save to Collection. If you do not have Mystic Extracts, reforge Mystic Scrolls at the altar to acquire them.  Epic Mystic Enchants unlock incredible power for your builds. They can grant entire new abilities and massively empower your existing abilities.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580143, -1, 15, -379, 64, 0, 'Path to Ascension: Legendary Mystic Enchant Collection', '- Acquire a Legendary Mystic Enchant Scroll by Reforging, discovering them in the world, or the Auction House.  - Visit an Altar and save a Legendary Mystic Enchants to your Enchant Collection.', 'Save a Legendary Enchant into your collection. You can Reforge Scrolls until you acquire a Legendary Enchant you''d like to save, or search the Auction House for Enchants that empower your spells and talents!  Visit an Altar and select a Legendary Mystic Scroll from the Scrolls tab, then hit Save to Collection. If you do not have Mystic Extracts, reforge Mystic Scrolls at the altar to acquire them.  Legendary Mystic Enchants unlock game-changing power. They can unlock entirely new archetypes, change the way you play entirely, and grant a massive power boost to your Hero.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580144, -1, 8, -379, 0, 0, 'Path to Ascension: Dungeon Diving', 'Defeat the final boss in any end game Normal Dungeon', 'Defeat the final boss in any end game Normal Dungeon', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
(580145, -1, 8, -379, 0, 0, 'Path to Ascension: Heroic Dungeons', 'Complete any Heroic Dungeon', 'Complete any Heroic Dungeon', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
(580146, -1, 8, -379, 0, 0, 'Path to Ascension: Normal Raiding', 'Defeat the final boss in any Normal Difficulty Raid', 'Defeat the final boss in any Normal Difficulty Raid', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
(580147, -1, 60, -379, 64, 0, 'Path to Ascension: Mythic Dungeons', 'Defeat the final boss in any Mythic Dungeon.', 'Open the Dungeon Finder and queue for a Random Mythic Dungeon or pick any of the available Mythic Dungeons under Specific Dungeons.  Mythic Dungeons are more challenging than Heroic Dungeons.   It is essential that you have full PvE gear and a well-prepared build before attempting a Mythic Dungeon.  Equip your PvE gear and defeat the final boss of any Mythic Dungeon!', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580148, -1, 60, -379, 64, 0, 'Path to Ascension: Mythic+ Dungeons', 'Complete any Mythic+ Dungeon.', 'Mythic+ Dungeons are timed dungeons of your favorite dungeons, but with a twist.  Creatures, bosses and normal mobs inside of Mythic+ Dungeons can be augmented with an Affix that will try to slow you down.  You are unable to queue for Mythic+ using the dungeon finder, so we advise you to advocate for members in guild chat or for world chat. Remember to have 1 tank, 1 healer and 3 dps for the Mythic+.  To begin a Mythic+ the leader of the group must have the rest of the group to travel to that instance (we suggest using a stone of retreat or the first-class-experimental teleporter).  Once inside, use your Keystone to begin the dungeon!', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580149, -1, 60, -379, 64, 0, 'Path to Ascension: Heroic Raiding', 'Defeat the final boss in any Heroic Raid', 'Defeat the final boss in any Heroic Raid', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580162, -1, 60, -379, 64, 0, 'Path to Ascension: Ascended Raiding', 'Defeat the final boss in any Ascended Raid', 'Defeat the final boss in any Ascended Raid', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580165, -1, 8, -379, 0, 0, 'Path to Ascension: Battlegrounds!', 'Complete any Battleground!', 'Complete any Battleground!', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
(580166, -1, 60, -379, 64, 0, 'Path to Ascension: 2v2 Solo Que', 'Join a 2v2 Arena Game using the Solo Queue function.', 'Did you know you can join a 2v2 game without queing with a partner?  On Ascension, you can be matched up with any player at any time for 2v2 battles.  To join any 2v2 game, open the PvP interface (H Keybind) and click the arena drop down tab.  After selecting the 2v2 rated arena battle, you can hit "Join Battle" to solo-que.  Our Matchmaking System will match you with the best currently available partner and put you in a 2v2 game.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580167, -1, 8, -379, 0, 0, 'Path to Ascension: Talk to an Arena Vendor', 'Visit and View any Arena Vendor''s Wares.', 'Visit and View any Arena Vendor''s Wares.', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
(580168, -1, 8, -379, 0, 0, 'Path to Ascension: Less Running, More Ressing', 'Resurrect safely in the nearest town or city next time you die!', 'Resurrect safely in the nearest town or city next time you die!', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
(580169, -1, 15, -379, 64, 0, 'Path to Ascension: Mystic Enchant Collector', 'Save 10 Mystic Enchants to your Enchant Collection.', 'Collecting Mystic Enchants and expanding your Enchant Collection will give you more options and more power.  There is no limit to the number of Mystic Enchants you can save to your Enchant Collection. You will continue earning Mystic Extracts from reforging Reforging, earned by completing various content, and can be bought from Nozdormu next to the Call Board for Gold or Marks of Ascension.  Save 10 Mystic Enchants to your collection.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580170, -1, 8, -379, 0, 0, 'Path to Ascension: Epic Riding', 'Learn Journeyman Riding from a Riding Tome or a Riding Trainer.', 'Learn Journeyman Riding from a Riding Tome or a Riding Trainer.', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
(580171, -1, 8, -379, 0, 0, 'Path to Ascension: Specialization II', 'Learn a Second Specialization.', 'Learn a Second Specialization.', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
(580172, -1, 8, -379, 0, 0, 'Path to Ascension: Bazaar Token', 'Buy any amount of Bazaar Tokens from the Auction House.', 'Buy any amount of Bazaar Tokens from the Auction House.', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
(580173, -1, 60, -379, 64, 0, 'Path to Ascension: Ethereal Bazaar', 'Buy any item from the Ethereal Bazaar.', 'Visit Tiraxis in your faction''s capital Auction House to view the Ethereal Bazaar wares.  The Ethereal Bazaar sells a limited stock of random Vanity items, spells and mounts. Tiraxis updates his inventory randomly multiple times per day from a pool of thousands of vanity items. There is always something new to discover on Tiraxis, and you may even be the first player to find a specific Vanity Item!  Only one player can buy a Vanity Item when Tiraxis updates his stock. When you buy an item form Tiraxis, no one else will be able to acquire that item until it is randomly selected in his stock again.  Talk to Tiraxis and purchase any item for Bazaar tokens. You can obtain Bazaar tokens from the Auction House!', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580174, -1, 60, -161, 64, 0, 'Path to Ascension: First Class Experimental Teleporter', 'Use the First Class Experimental Teleporter.', 'The First Class Experimental Teleporter allows you to get from the Capital City into the World or into other capital cities in a jiffy.  This Teleporter is located in popular parts of the Capital Cities, it stands out and you won''t miss it.  You will be dropped hundreds of yards into the air, don''t worry, we provide a parachute that lasts just long enough to get you to the ground... safely.  ', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580175, -1, 1, -379, 64, 0, 'Path to Ascension: Wargames', 'Complete any Wargame.', 'Wargames are a feature on Ascension that allows you to Queue up any Battleground or Arena with the cost of having no queue timer.  Wargames allow you to test out your build for free and play against your friends or foes before taking it into the Rated Arenas or allows your guild to duke it out with your rival guild.  To queue for a Wargame, locate Teri Glozilk in any Capital City.  Find the friend or foe you wish to play against, select your battleground or arena (we recommend arena for small-scale fights) then begin the fight.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580176, -1, 8, -379, 0, 0, 'Path to Ascension: Titan Scrolls', 'Use any Titan Scroll.', 'Use any Titan Scroll.', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
(580179, -1, 8, -379, 0, 0, 'Path to Ascension: Take Down a World Boss', 'Slay any World Boss.', 'Slay any World Boss.', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
(580181, -1, 60, 11211, 64, 0, 'Path to Ascension: Complete an Invasion', 'Defeat an Invasion Boss.', 'An invasion is a periodic World Event that spawns throughout Azeroth that scales to how many players are near the zone.  To find an invasion, you can look on your World Map or ask in World Chat if one is currently up.  To complete an invasion, you must kill the FInal Boss. Once entering an invasion, a percentage completion counter will appear. Once this counter reaches 100% the final boss will appear.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580182, -1, 15, -379, 64, 0, 'Path to Ascension: Using Your Mystic Enchant Collection', 'Visit an Altar and apply a Mystic Enchant from your Enchant Collection to an Active Enchant slot.', 'Open the Enchant Collection tab from a Mystic Altar, select an Enchant from your Enchant Collections and apply it to an Active Enchant slot, then select Save Changes to activate your Mystic Enchant.  Activating Enchants from your collection requires Mystic Orbs, which can be earned from Daily Quests on the Call Board, Dungeons and Raids, Battlegrounds or defeating enemies in the world!  1 Legendary Enchant can be applied to the large center slot in the Altar.  3 Epic Enchants can be applied in the medium slots in the inner ring.  You can apply as many Rare and Uncommon Enchants in the remaining slots as you''d like. Many of these Enchants can stack up to 3 times. Mousing over the Enchant in the collection reveals its max stack size.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580183, -1, 60, -379, 64, 0, 'Path to Ascension: Prestige', 'Talk to Chromie next to the Call Board in your capital city if you would like to Prestige. This will reset you to level 1! You can abandon this quest if you do not want to Prestige.', 'Choosing to Prestige will reset your character to level 1 and teleport you to your starting zone.  Prestige is a great way to earn gear, Mystic Enchanting supplies, Marks of Ascension and more! Re-experience the leveling journey, Dungeons and Battlegrounds with all the knowledge you have acquired, including your saved Mystic Enchants!  What happens:  - Your current specialization is reset. - Your equipped gear will be mailed to you. - All leveling quests will be reset and available to be completed again. - Your quest log will be wiped.  Prestiging in Wildcard resets your currently selected specialization!    Your current Wildcard Specialization will: - Unlearn all spells and talents. This resets your active build! - Removes Scrolls of Fortune for that specialization. - Resets Scroll of Fortune quests at Silas for that specialization. - Removes Cases of Fortune. - All other Specs will remain locked until you reach max level. - You can activate new Skill Cards for your Prestiged Spec. - Your equipped gear will be mailed to you. - All leveling quests will be reset and available to be completed again. - Your quest log will be wiped.  You will keep all professions, gear, Marks of Ascension, currencies and items except for your Prestiged Spec''s Unspent Hand of Fates. If you have advanced riding training you will receive a tome that will allow you to relearn your riding at the appropriate level.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580184, -1, 8, -379, 0, 0, 'Path to Ascension: Badges of Justice', 'Complete any Heroic Dungeon', 'Complete any Heroic Dungeon', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
(580186, -1, 50, -379, 64, 0, 'Path to Ascension: Fully Mystic Enchanted', 'Activate a Mystic Enchant in all 17 Active Enchant Slots.', 'Open the Enchant Collection tab from a Mystic Altar, select Enchants from your Enchant Collections and fill all empty Active Enchant slots! Collect more relevant Mystic Enchants if you cannot fill all 17 Active Enchant slots.  Activating Enchants from your collection requires Mystic Orbs, which can be earned from Daily Quests on the Call Board, Dungeons and Raids, Battlegrounds or defeating enemies in the world!  1 Legendary Enchant can be applied to the large center slot in the Altar.  3 Epic Enchants can be applied in the medium slots in the inner ring.  You can apply as many Rare and Uncommon Enchants in the remaining slots as you''d like. Many of these Enchants can stack up to 3 times. Mousing over the Enchant in the collection reveals its max stack size.  Fill all 17 Active Enchant slots!', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580187, -1, 15, -379, 64, 0, 'Path to Ascension: Activate a Legendary Mystic Enchant', 'Activate a Legendary Mystic Enchant.', 'Open the Enchant Collection tab from a Mystic Altar, select a Legendary Enchant from your Enchant Collections and apply it to the center Active Enchant slot!    Activating Enchants from your collection requires Mystic Orbs, which can be earned from Daily Quests on the Call Board, Dungeons and Raids, Battlegrounds or defeating enemies in the world!    You can only have 1 Legendary Enchant active at a time.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580188, -1, 15, -379, 64, 0, 'Path to Ascension: Activate Epic Mystic Enchants', 'Activate 3 Epic Mystic Enchants.', 'Open the Enchant Collection tab from a Mystic Altar, select an Epic Enchant from your Enchant Collections and apply it to one of the 3 Epic Active Enchant slots!    Activating Enchants from your collection requires Mystic Orbs, which can be earned from Daily Quests on the Call Board, Dungeons and Raids, Battlegrounds or defeating enemies in the world!    You can have 3 different Epic Enchants active at a time.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580189, -1, 70, -379, 64, 0, 'Path to Ascension: Mystic Enchant Specializations', '- Open your Enchant Collection from the Character Advancement menu or use an Altar.  - Click the ''Change'' button at the bottom left to change your Enchant Specialization.  - Select a different Specialization then Activate.', 'You start with 2 Mystic Enchant Specializations. You can swap your Enchant Specialization anytime outside of combat for free!     Unlocking a new Specialization with a Tome of Specialization will also unlock a new Enchant Specialization. Use Mystic Enchant: Specialization tomes to unlock even more Enchant specs!    Mystic Enchanting Specializations allow you to create different loadouts for your Active Enchants. This allows you to:   - Swap your enchants to try out different builds on the fly.   - Maintain different Enchant loadouts if you use multi-spec to play different builds.  - Adapt to specific scenarios and encounters.  - Quickly switch between PvE and PvP Enchant loadouts.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580190, -1, 15, -379, 64, 0, 'Path to Ascension: Worldforged Enchants', 'Save a Worldforged Mystic Enchant to your Enchant Collection.', 'Worldforged Mystic Enchants cannot be traded or found when Reforging at the Altar. These soulbound Mystic Enchants must be discovered in the world!    Acquire a Worldforged Mystic Enchant Scroll and save it to your collection.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580191, -1, 60, -379, 64, 0, 'Path to Ascension: Mark of Triumph', 'Travel to Stormwind Keep and speak to Markus', 'Marks of Triumph are earned by completing Heroic and Mythic difficulty dungeons.    These marks can be exchanged for gear! Use them to upgrade your gear or save up for specific equipment key to your build.    Visit Markus in the Stormwind Throne Room to see the gear you can acquire.', 'Talk to Markus in the Stormwind Throne Room.', 0, 0, 0, 0, '', ''),
(580192, -1, 60, -379, 64, 0, 'Path to Ascension: Mark of Triumph', 'Travel to Orgrimmar''s Valley of Wisdom and speak to Mar''toge', 'Marks of Triumph are earned by completing Heroic and Mythic difficulty dungeons.    These marks can be exchanged for gear! Use them to upgrade your gear or save up for specific equipment key to your build.    Travel to Orgrimmar and speak with Mar''toge in the Valley of Wisdom throne room to see the gear you can acquire.', 'Visit Mar''toge in Orgrimmar''s Valley of Wisdom throne room.', 0, 0, 0, 0, '', ''),
(580193, -1, 50, -379, 64, 0, 'Path to Ascension: Fully Mystic Enchanted', 'Activate a Mystic Enchant in all 17 Active Enchant Slots.', 'Open the Enchant Collection tab from a Mystic Altar, select Enchants from your Enchant Collections and fill all empty Active Enchant slots! Collect more relevant Mystic Enchants if you cannot fill all 17 Active Enchant slots.  Activating Enchants from your collection requires Mystic Orbs, which can be earned from Daily Quests on the Call Board, Dungeons and Raids, Battlegrounds or defeating enemies in the world!  Wildcard Heroes can only use Rare and Uncommon Enchants and most stack up to 3 times! Mousing over the Enchant in the collection reveals its max stack size.  Fill all 17 Active Enchant slots with Rare and Uncommon Enchants!', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580194, -1, 15, -379, 64, 0, 'Path to Ascension: Mystic Enchant Collector', 'Save 10 Mystic Enchants to your Enchant Collection.', 'Collecting Mystic Enchants and expanding your Enchant Collection will give you more options and more power.  There is no limit to the number of Mystic Enchants you can save to your Enchant Collection. You will continue earning Mystic Extracts from reforging Reforging, earned by completing various content, and can be bought from Nozdormu next to the Call Board for Gold or Marks of Ascension.  Save 10 Mystic Enchants to your collection.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580195, -1, 15, -379, 64, 0, 'Path to Ascension Wildcard: Reroll Spells', '- Speak to Silas Darkmoon in your Capital City to acquire Scrolls of Fortune.  - Open your Character Advancement menu with N or from the menu bar.  - Click an ability you would like to reroll and select Unlearn.', 'The spells and abilities you learn in Wildcard can be rerolled using Scrolls of Fortune!    Silas Darkmoon will grant you free Scrolls of Fortune every 10 levels and offers Scrolls of Fortune at max level for Marks of Ascension.    Try to Reroll your least used spells and abilities that are not increasing your build''s potential. As you continue rerolling the spells that help you the least, you will acquire more and more spells that significantly empower your build.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580196, -1, 15, -379, 64, 0, 'Path to Ascension Wildcard: Reroll Talents', '- Speak to Silas Darkmoon in your Capital City to acquire Scrolls of Fortune.  - Open your Character Advancement menu with N or from the menu bar.  - Click a Talent you would like to reroll and select Unlearn.', 'The Talents you learn in Wildcard can be rerolled using Scrolls of Fortune: Talents and Scrolls of Fortune!    Silas Darkmoon will grant you free Scrolls of Fortune every 10 levels and offers Scrolls of Fortune at max level for Marks of Ascension.    Try to Reroll talents that do not directly increase your power or empower abilities you use first! As you reroll your weakest or least relevant talents, your build will quickly fill up with talents that all add immense power.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580197, -1, 15, -379, 64, 0, 'Path to Ascension Wildcard: Locking Spells and Talents', '- Open the Character Advancement Menu  - Select the Lock icon on an ability or talent you would like to lock', 'You can lock Spells and Talents you don''t want to accidentally unlearn or reroll! These can be unlocked at any time.    Locked Spells and Talents also sort to the top. This allows you to quickly find spells and talents to reroll and ensures you don''t reroll ones you are not ready to!    The locking system both protects your build and makes rerolling easier.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580198, -1, 15, -379, 64, 0, 'Path to Ascension Wildcard: Skill Card Packs', '- Visit Silas Darkmoon in a Capital City - Complete max level Scroll of Fortune quests to earn Sealed Card Packs. - Use your Sealed Card Pack to open it.', 'Sealed Card Packs contain max-level Talent Skill Cards.  Open these packs to collect Skill Cards you can use to gain more control of future builds or guarantee talents in your current one.  Cards revealed from packs are automatically added to your account-wide Skill Card Collection.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580199, -1, 15, -379, 64, 0, 'Path to Ascension Wildcard: Golden Skill Cards', '- Visit Silas Darkmoon in a Capital City  - Select Golden Skill Cards Menu and buy a Golden Pack  - Use your Golden Sealed Card Pack to open it.', 'Golden Sealed Card Packs contain Golden Skill Cards!    Golden Skill Cards Packs and Golden Cards function the same as normal Skill Cards, but they can fill the Golden Skill Card slots, allowing even more control of your build as you begin collecting these cards.    These packs are also acquired periodically when opening Normal Skill Card packs as your duplicate cards are transformed into progress towards free card packs.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580200, -1, 15, -379, 64, 0, 'Path to Ascension Wildcard: Darkmoon Tickets', '- Visit Silas Darkmoon in a Capital City  - Select Darkmoon Prizes Menu, the Prizes  - Buy a Darkmoon Ticket Pouch(25)', 'You earn Darkmoon tickets when you open Sealed Card Packs.    These tickets can be redeemed at Silas Darkmoon to buy Normal, Uncommon, Rare, and Epic Skill Cards. Save up your tickets to acquire key skill cards for your build.    You can also buy cosmetic prizesm for Darkmoon tickets. Darkmoon Pouches allow you to transfer Darkmoon tickets between other characters on your account.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
(580201, -1, 15, -379, 64, 0, 'Path to Ascension Wildcard: Activate a Skill Card', '- Open Character Advancement - Click the Skill Cards tab - Activate a Skill Card while you are level 1-9.', 'Activating Skill Cards guarantees that you will roll that Spell or Talent.  Skill Cards can only be activated while you are levels 1-9. You can add Skill Cards to your collection at any time, and your Skill Card Collection is shared across all characters on your account. New characters and Prestiged characters can use cards you have already collected.  If you use multiple specializations, you can use Skill Cards in a specialization until that specialization rolls its 5th spell.', 'Return to the Call Board.', 0, 0, 0, 0, NULL, NULL),
