(1903546, -1, 8, -379, 0, 0, 'Path to Ascension: Report to the Flightmaster', 'Speak to Doras the Flightmaster at top of the tower next to the Ogrimmar Bank.', 'Speak to Doras the Flightmaster at top of the tower next to the Ogrimmar Bank.', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
(1903547, -1, 8, -379, 0, 0, 'Path to Ascension: Report to the Flightmaster', 'Head to the East Corner of the Trade District, then follow the ramp up, speak to Dungar Longdrink.', 'Head to the East Corner of the Trade District, then follow the ramp up, speak to Dungar Longdrink.', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
