(1903555, -1, 8, -379, 0, 0, 'Path to Ascension: Faster Riding!', 'Learn Apprentice Riding Training. Speak to Randal Hunter at the Eastvale Logging Camp outside Stormwind in Elwynn Forest and select "I seek to training to ride a steed."', 'Learn Apprentice Riding Training. Speak to Randal Hunter at the Eastvale Logging Camp outside Stormwind in Elwynn Forest and select "I seek to training to ride a steed."', 'Collect the reward in Path to Ascension.', 0, 0, 0, 0, NULL, NULL),
